		t.Fatal("the second validation started nothing")
	}
	if firstCtx.Err() != context.Canceled {
		t.Errorf("the first lot's context = %v, want Canceled", firstCtx.Err())
	}
	if m.registryBrowser.gen == oldGen {
		t.Error("gen did not change")
	}
	pending := m.registryBrowser.pendingSearches
	for _, msg := range first {
		if r, ok := msg.(ImageSearchResultMsg); ok {
			m, _ = step(t, m, r)
		}
	}
	if m.registryBrowser.pendingSearches != pending {
		t.Errorf("pendingSearches = %d, want %d: a stale answer must not count", m.registryBrowser.pendingSearches, pending)
	}
	if n := len(m.registryBrowser.searchTable.Visible()); n != 0 {
		t.Errorf("%d rows from a stale answer", n)
	}
}

func TestTheRegistryDeadlineIsFifteenSeconds(t *testing.T) {
	if got := imageSearchDeadline.Seconds(); got != 15 {
		t.Errorf("imageSearchDeadline = %vs, want 15", got)
	}
}

package ociresources

import (
	"context"
	"sync/atomic"

	"github.com/anthnel/devdesk/internal/oci"
)

// browserGen numbers the lots of tag requests across every browser instance,
// so an answer from a browser closed and reopened since is never taken for the
// open one's. Zero is never handed out: it means "no lot".
var browserGen atomic.Uint64

// listRegistryTags is the seam the tag search reads a registry through; tests
// swap it.
var listRegistryTags = oci.ListRegistryTagsContext

// nextBrowserGen returns a fresh generation. Called from Update only (Rule 110).
func nextBrowserGen() uint64 { return browserGen.Add(1) }

// beginRequests cancels the lot in flight and opens a new one: a new
// generation, a fresh context, no pending search. Call it only once a request
// is certain to start, so a refused validation leaves the running lot alone.
func (b *RegistryBrowser) beginRequests() context.Context {
	b.cancelInFlight()
	ctx, cancel := context.WithCancel(context.Background())
	b.cancel = cancel
	b.gen = nextBrowserGen()
	b.pendingSearches = 0
	return ctx
}

// cancelInFlight cancels the lot's context, if any. Nil-safe.
func (b *RegistryBrowser) cancelInFlight() {
	if b == nil || b.cancel == nil {
		return
	}
	b.cancel()
	b.cancel = nil
}

// RegistryBrowserGen returns the generation the open browser accepts, 0 when it
// is closed. For tests, like ActivityTables.
func (m Model) RegistryBrowserGen() uint64 {
	if m.registryBrowser == nil {
		return 0
	}
	return m.registryBrowser.gen
}
package ociresources

import (
	"strings"

	tea "charm.land/bubbletea/v2"

	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/docker"
	"github.com/anthnel/devdesk/internal/ui/keymap"
)

// InEditMode returns true when a text input is active (blocks command mode).
func (b *RegistryBrowser) InEditMode() bool {
	if b.state == browserStateInput && b.focusedField == brFieldRepo {
		return true
	}
	return b.state == browserStateTags && b.filterActive
}

// IsSearching returns true while registry tag queries are still in flight.
func (b *RegistryBrowser) IsSearching() bool {
	return b.pendingSearches > 0
}

// Update handles all messages for the browser.
func (b *RegistryBrowser) Update(msg tea.Msg) (*RegistryBrowser, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.KeyPressMsg:
		return b.handleKeyMsg(msg)
	}
	return b.delegateUpdate(msg)
}

func (b *RegistryBrowser) delegateUpdate(msg tea.Msg) (*RegistryBrowser, tea.Cmd) {
	if b.state == browserStateInput && b.focusedField == brFieldRepo {
		var cmd tea.Cmd
		b.repoInput, cmd = b.repoInput.Update(msg)
		return b, cmd
	}
	if b.state == browserStateTags {
		if b.filterActive {
			var cmd tea.Cmd
			b.filterInput, cmd = b.filterInput.Update(msg)
			b.rebuildTagTable()
			return b, cmd
		}
		return b, b.tagTable.Update(msg)
	}
	return b, nil
}

func (b *RegistryBrowser) handleKeyMsg(msg tea.KeyPressMsg) (*RegistryBrowser, tea.Cmd) {
	switch b.state {
	case browserStateInput:
		return b.handleInputKeyMsg(msg)
	case browserStateTags:
		return b.handleTagsKeyMsg(msg)
	}
	return b, nil
}

func (b *RegistryBrowser) handleInputKeyMsg(msg tea.KeyPressMsg) (*RegistryBrowser, tea.Cmd) {
	switch msg.String() {
	case "esc":
		return b, func() tea.Msg { return RegistryBrowserCloseMsg{} }
	case "down":
		b.focusedField = min(b.focusedField+1, b.brFieldSubmit())
		b.updateFocus()
		return b, nil
	case "up":
		b.focusedField = max(b.focusedField-1, brFieldRepo)
		b.updateFocus()
		return b, nil
	case keymap.Space:
		if b.focusedField >= 1 && b.focusedField <= len(b.rows) {
			row := b.rows[b.focusedField-1]
			if row.groupSlug != "" {
				b.toggleGroup(row.groupSlug)
				return b, nil
			}
			key := b.entries[row.entry].key
			b.selectedRegs[key] = !b.selectedRegs[key]
			return b, nil
		}
	case "enter":
		if b.focusedField == brFieldRepo || b.focusedField == b.brFieldSubmit() {
			return b.submitSearch()
		}
		b.focusedField = min(b.focusedField+1, b.brFieldSubmit())
		b.updateFocus()
		return b, nil
	}
	return b.delegateUpdate(msg)
}

// credsFor returns the credentials to search entry with, and nothing at all
// when the registry — or the group it belongs to — is marked anonymous (D12).
// Docker keys credentials by host, so a Nexus instance with one repository
// logged into would otherwise send that login to every repository it serves.
func (b *RegistryBrowser) credsFor(entry browserRegistryEntry) (string, string) {
	if !config.UsesCredentials(entry.authMode) {
		return "", ""
	}
	// Credentials come from the parent registry, or the entry itself for a
	// registry that is not a group member.
	credURL := entry.URL
	if entry.parentURL != "" {
		credURL = entry.parentURL
	}
	var username string
	for _, reg := range b.registries {
		if reg.URL == credURL {
			username = reg.Username
			break
		}
	}
	storedUser, storedPass, _ := docker.GetStoredCreds(credURL)
	if username == "" {
		username = storedUser
	}
	return username, storedPass
}

func (b *RegistryBrowser) submitSearch() (*RegistryBrowser, tea.Cmd) {
	repo := strings.TrimSpace(b.repoInput.Value())
	if repo == "" {
		return b, nil
	}

	// Gather the requests first: a validation that starts none must leave the
	// lot in flight, its generation and its context alone.
	type request struct {
		entry                         browserRegistryEntry
		alias, apiURL, repo, user, pw string
	}
	var reqs []request
	for _, entry := range b.entries {
		if !b.selected(entry) {
			continue
		}
		username, storedPass := b.credsFor(entry)
		alias := entry.Alias
		if entry.ParentAlias != "" {
			alias = entry.ParentAlias + "/" + entry.Alias
		}
		// The prefix is applied here and nowhere else: it is then already part
		// of MultiRegistryTag.Repo, so multiImageName and registryAPIURL need to
		// know nothing about it. Teaching both would be two places free to
		// drift, which is the disagreement D39 already is (§3.18).
		normalizedRepo := joinRepoPrefix(entry.repoPrefix, normalizeRepoForRegistry(entry.URL, repo))
		reqs = append(reqs, request{entry, alias, registryAPIURL(entry.URL), normalizedRepo, username, storedPass})
	}
	if len(reqs) == 0 {
		return b, nil
	}

	ctx := b.beginRequests()
	b.tags = nil
	b.registryFilter = resultFilter{}
	b.filterInput.SetValue("")
	b.filterActive = false
	// A new search starts from the default order, not wherever the last one's
	// `.` presses left the table.
	b.tagTable.SetSort(tagColumnTag, false)

	cmds := make([]tea.Cmd, 0, len(reqs))
	for _, r := range reqs {
		b.pendingSearches++
		cmds = append(cmds, searchRegistryTagsCmd(ctx, b.gen, r.entry.key, r.entry.URL, r.alias, r.apiURL, r.repo, r.user, r.pw))
	}

	b.state = browserStateTags
	b.tagTable.Focus()
	b.rebuildTagTable()
	return b, tea.Batch(cmds...)
}

func (b *RegistryBrowser) handleTagsKeyMsg(msg tea.KeyPressMsg) (*RegistryBrowser, tea.Cmd) {
	if b.filterActive {
		switch msg.String() {
		case "esc", "enter":
			b.filterActive = false
			b.filterInput.Blur()
			b.rebuildTagTable()
			b.resizeTagTable()
			return b, nil
		}
		return b.delegateUpdate(msg)
	}

	switch msg.String() {
	case "esc":
		b.state = browserStateInput
		b.tagTable.Blur()
		b.updateFocus()
		return b, nil
	case "/":
		b.filterActive = true
		b.filterInput.Focus()
		b.resizeTagTable()
		return b, nil
	case "r":
		b.cycleRegistryFilter()
		return b, nil
	case "enter":
		return b.openTagScanDetails()
	case keymap.Get:
		return b.pullSelectedTag()
	case keymap.Scan:
		return b.requestDirectScan()
	}
	// Navigation and `.` are the table's. `/` never reaches it: the browser's
	// own filter took the key two cases above, and the table declares no
	// searchable column, so it would decline it anyway.
	return b, b.tagTable.Update(msg)
}
package ociresources

import (
	"slices"
	"time"

	"github.com/anthnel/devdesk/internal/cache"
	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/ui/indicator"
)

// AddRegistryTags incorporates results from one registry into the combined tag list.
// Always decrements pendingSearches, even on error (tags will be nil).
func (b *RegistryBrowser) AddRegistryTags(entryKey, registryURL, alias, repo string, tags []string) {
	// Floored: a duplicate or late response would otherwise drive the counter
	// negative, and the next search would start from that base — IsSearching()
	// would stay false while requests were genuinely in flight, so the spinner
	// never showed.
	if b.pendingSearches > 0 {
		b.pendingSearches--
	}
	for _, tag := range tags {
		b.tags = append(b.tags, MultiRegistryTag{
			EntryKey:    entryKey,
			RegistryURL: registryURL,
			Alias:       alias,
			Repo:        repo,
			Tag:         tag,
		})
	}
	if b.state == browserStateTags {
		b.rebuildTagTable()
	}
}

// SetMultiTagsMeta stores last-updated metadata for tags belonging to one entry.
//
// Keyed on the entry, not the host: several entries share one host once a
// registry is a host plus a repo prefix, so a URL would stamp one proxy's dates
// onto every proxy of that instance (§3.18).
func (b *RegistryBrowser) SetMultiTagsMeta(entryKey string, meta map[string]time.Time) {
	for i := range b.tags {
		if b.tags[i].EntryKey != entryKey {
			continue
		}
		if t, ok := meta[b.tags[i].Tag]; ok {
			b.tags[i].UpdatedAt = t
		}
	}
	if b.state == browserStateTags {
		b.rebuildTagTable()
	}
}

// SetJobs takes the router's snapshot — what is running or remembered as
// failed, and the context it is read in — and rebuilds the rows.
//
// A snapshot rather than one name at a time: it says what is running rather
// than what changed, and reconciling a whole answer against per-name edits is
// how the two drift.
func (b *RegistryBrowser) SetJobs(runs []jobs.Run, failures []jobs.Failure, context string) {
	b.jobs = runs
	b.failures = slices.Clone(failures)
	b.contextName = context
	if b.state == browserStateTags {
		b.rebuildTagTable()
	}
}

// SetBlinkPhase hands the router's blink phase to the tag table. Nothing is
// rebuilt: the table reads the phase at render.
func (b *RegistryBrowser) SetBlinkPhase(on bool) { b.tagTable.SetBlinkPhase(on) }

// WantsBlink reports whether a visible tag row has a running operation.
func (b *RegistryBrowser) WantsBlink() bool {
	if b.state != browserStateTags {
		return false
	}
	for _, r := range b.tagTable.Items() {
		if r.Activity.State == indicator.Running {
			return true
		}
	}
	return false
}

// HasSelectedTagScanResults returns true when the selected tag has cached scan results.
func (b *RegistryBrowser) HasSelectedTagScanResults() bool {
	name := b.selectedImageName()
	if name == "" {
		return false
	}
	_, ok := b.scanCache[name]
	return ok
}

// SetScanCache stores the model's scan cache for CVE column display.
func (b *RegistryBrowser) SetScanCache(sc map[string]cache.ImageScanEntry) {
	b.scanCache = sc
	if b.state == browserStateTags {
		b.rebuildTagTable()
	}
}

// SetOperationError, SetOperationSuccess and OperationImageName went with the
// status screen (§3.60): the browser is closed by the time a pull answers, and
// the answer goes to the footer and the Images list.

// selectedImageName returns the full image reference for the focused table row.
func (b *RegistryBrowser) selectedImageName() string {
	t := b.getSelectedMultiTag()
	if t == nil {
		return ""
	}
	return multiImageName(t.RegistryURL, t.Repo, t.Tag)
}

// getSelectedMultiTag returns the MultiRegistryTag under the cursor, or nil.
//
// It used to replay the filter and the sort to map the cursor back to a tag,
// with nothing tying that ordering to the one the rows were built from. The
// table keeps the ordered slice it drew, so the two cannot disagree.
func (b *RegistryBrowser) getSelectedMultiTag() *MultiRegistryTag {
	row, ok := b.tagTable.Selected()
	if !ok {
		return nil
	}
	return &row.tag
}
package ociresources

import (
	"context"
	"strconv"
	"strings"

	"charm.land/bubbles/v2/textinput"

	"charm.land/lipgloss/v2"

	"github.com/anthnel/devdesk/internal/cache"
	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/indicator"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// browserState tracks which screen the browser is on.
type browserState int

// browserStateResolving is gone. The browser used to open into it and ignore
// every key — esc included — while up to one 8-second detection per configured
// registry ran (D13). Members now come from config plus the group cache, so
// there is nothing to resolve and the form renders at once, offline included.
// browserStateStatus is gone too (§3.60). It was the spinner the browser showed
// while a pull ran, and a pull is a job now: the row spins in the Images tab,
// which is where asking for one leaves the user.
const (
	browserStateInput browserState = iota // search form
	browserStateTags                      // results table
)

// browserRegistryEntry is one selectable registry in the browser form.
// Group members have ParentSlug set; standalone registries have it empty.
type browserRegistryEntry struct {
	URL   string
	Alias string
	// repoPrefix goes in front of the repository name. With URL it forms the
	// entry's address, and both the browse path and the pull reference derive
	// from that one pair — which is what stops them meaning two different
	// repositories (D39, §3.18).
	repoPrefix string
	// Slug identifies the entry: its own for a standalone registry, its group's
	// for a member. It is what the result filter resolves labels through, and
	// what replaced matching on URL — two registries configured with the same
	// URL used to collide.
	Slug        string
	ParentAlias string // non-empty = member of a group
	ParentSlug  string
	parentURL   string // URL of the parent RegistryItem (for credential lookup)
	// key identifies the entry among all the others, and is what the checkbox,
	// the remembered exclusions and every result are keyed on (D40). It is not
	// the URL: two registries may be declared on one host — the form enforces
	// slug uniqueness, not URL uniqueness — and §3.18 makes that the ordinary
	// case, since a member is now a bare host plus a prefix. Nor is it Slug,
	// which holds the *group's* slug for a member and would give a whole group
	// one checkbox. So: the slug for a standalone registry, and the group's slug
	// plus the member's address for a member — the address, not the alias:
	// cleanMemberAlias strips `-proxy` and `-hosted`, so `docker-io-proxy` and
	// `docker-io-hosted` both display as `docker-io`.
	key string
	// authMode is already resolved: a member carries what its group settled on,
	// since `inherit` is the only thing the shared credential entry can mean.
	authMode string
}

// resultFilter narrows the tag table to one group or one registry. Both empty
// means everything.
//
// The single-registry level is an entry key rather than a URL: several entries
// share one host once a member is a host plus a prefix, so a URL would select
// every proxy on that instance at once (§3.18, and D40 one screen along).
type resultFilter struct {
	groupSlug string
	entryKey  string
}

func (f resultFilter) isEmpty() bool { return f.groupSlug == "" && f.entryKey == "" }

// matches reports whether a result from entryKey passes the filter. A group
// matches every one of its members, which is what the group level is for.
func (f resultFilter) matches(entryKey string, entry *browserRegistryEntry) bool {
	switch {
	case f.isEmpty():
		return true
	case f.groupSlug != "":
		return entry != nil && entry.ParentSlug == f.groupSlug
	default:
		return entryKey == f.entryKey
	}
}

// pickerRow is one line of the registry picker. A group is a row of its own
// whose checkbox covers its members, which is the only way to select eight
// proxies without eight keystrokes.
type pickerRow struct {
	// groupSlug is set on a group header; entry is -1 there.
	groupSlug string
	label     string
	entry     int // index into b.entries, or -1
}

// tagRow is one line of the tag table: the tag, plus what the row says about it
// that does not live on the tag — the registry's display label, the cached scan
// counts, what the activity column says and whether a scan is running.
//
// The columns are built once, in newRegistryBrowser, so their Cell functions
// cannot reach back into the browser for any of that. It is the imageRow
// pattern, and it exists for the same reason: a column sorts by the value it
// prints.
type tagRow struct {
	tag     MultiRegistryTag
	label   string // registry alias, or its URL when it has none
	entry   cache.ImageScanEntry
	scanned bool
	// Activity is what the first column and the footer say: a scan or a pull
	// running, queued or failed, resolved by rebuildTagTable. It carries no
	// animation phase; the table reads it at render.
	Activity components.RowActivity
	// ScanRunning is true while a scan of the tag really runs (not queued): the
	// severity cells then hold a placeholder instead of the counts.
	ScanRunning bool
}

// tagColumns describes the tag results table.
func tagColumns() []datatable.Column[tagRow] {
	return []datatable.Column[tagRow]{
		// The activity column (Rule 125): untitled, no Less nor Search, empty at rest.
		datatable.IndicatorColumn(func(r tagRow) indicator.State { return r.Activity.State }, nil, nil),
		{
			Title: "Registry", Sizing: datatable.SizingContent, MinWidth: 20,
			Cell: func(r tagRow) string { return r.label },
		},
		{
			Title: "Tag", Sizing: datatable.SizingContent, MinWidth: 30, Flex: 1,
			Cell: func(r tagRow) string { return r.tag.Tag },
			Less: func(a, b tagRow) bool {
				return strings.ToLower(a.tag.Tag) < strings.ToLower(b.tag.Tag)
			},
		},
		{
			Title: "Updated", Sizing: datatable.SizingFixed, Optional: true, MinWidth: 16,
			Cell: func(r tagRow) string {
				if r.tag.UpdatedAt.IsZero() {
					return "-"
				}
				return theme.TimeAgo(r.tag.UpdatedAt)
			},
			// Newest first is this column's ascending order: "most recently
			// updated" is what anyone sorting by it is after.
			Less: func(a, b tagRow) bool { return a.tag.UpdatedAt.After(b.tag.UpdatedAt) },
		},
		tagCVEColumn("C", func(e cache.ImageScanEntry) int { return e.Critical }),
		tagCVEColumn("H", func(e cache.ImageScanEntry) int { return e.High }),
		tagCVEColumn("M", func(e cache.ImageScanEntry) int { return e.Medium }),
		tagCVEColumn("L", func(e cache.ImageScanEntry) int { return e.Low }),
	}
}

// tagCVEColumn builds one of the four severity count columns: a dim ellipsis
// while a scan runs, the count once one has, and a dash for a tag never scanned —
// nought findings and never looked at are different answers. A queued scan or a
// pull keeps the counts.
func tagCVEColumn(title string, get func(cache.ImageScanEntry) int) datatable.Column[tagRow] {
	return datatable.Column[tagRow]{
		Title: title, Sizing: datatable.SizingFixed, MinWidth: 4,
		Cell: func(r tagRow) string {
			switch {
			case r.ScanRunning:
				return "…"
			case r.scanned:
				return strconv.Itoa(get(r.entry))
			default:
				return "-"
			}
		},
		Style: func(r tagRow) lipgloss.Style {
			if r.ScanRunning {
				return theme.DimStyle
			}
			return lipgloss.NewStyle()
		},
	}
}

// newTagTable builds the tag table. ActivityTables uses it too, so the guard
// sees the real columns even with the browser closed.
func newTagTable() *datatable.Model[tagRow] {
	t := datatable.New(datatable.Config[tagRow]{
		Columns:    tagColumns(),
		SortColumn: tagColumnTag,
	})
	return &t
}

const brFieldRepo = 0

// brFieldReg returns the form field index for the i-th picker row.
func (b *RegistryBrowser) brFieldReg(i int) int { return 1 + i }

// brFieldSubmit returns the form field index for the Browse Tags button.
func (b *RegistryBrowser) brFieldSubmit() int { return 1 + len(b.rows) }

// RegistryBrowserCloseMsg is sent when the user presses ESC on the browser input screen.
type RegistryBrowserCloseMsg struct{}

// The two sortable columns of the tag table. `.` cycles Tag ascending, Tag
// descending, Updated, Updated descending and back — which is what
// datatable.CycleSort does over exactly these two, so the cycle is no longer
// written out.
const (
	tagColumnTag     = 2
	tagColumnUpdated = 3
)

// RegistryBrowser searches image tags across multiple configured registries.
type RegistryBrowser struct {
	registries    []config.RegistryItem
	width, height int

	// Entries, built once from config plus the group cache.
	entries []browserRegistryEntry
	rows    []pickerRow

	// Form state
	repoInput    textinput.Model
	selectedRegs map[string]bool // entry key → checked
	focusedField int

	// Results state
	tags            []MultiRegistryTag
	pendingSearches int
	// gen names the lot of requests whose answers the browser takes, and cancel
	// stops that lot (browser_flow.go).
	gen            uint64
	cancel         context.CancelFunc
	registryFilter resultFilter
	tagTable       datatable.Model[tagRow]
	scanCache      map[string]cache.ImageScanEntry

	// The router's snapshot, for the activity column and the footer: the
	// registry's runs and remembered failures, and the context they are read in.
	jobs        []jobs.Run
	failures    []jobs.Failure
	contextName string

	// Tag filter in the results view. The sort belongs to the table now; this
	// filter stays here because it narrows the tags before the table sees them,
	// alongside registryFilter, and because it is drawn in the OCI view's own
	// footer rather than the table's bar.
	filterInput  textinput.Model
	filterActive bool

	state browserState
}

// newRegistryBrowser creates a RegistryBrowser showing its form immediately.
//
// A group's members come from the cache the Registries tab refreshes, so
// opening the browser reads a file rather than the network — which is what
// removed the resolving state D13 is about, rather than papering over it.
func newRegistryBrowser(
	registries []config.RegistryItem,
	groups map[string]cache.RegistryGroupEntry,
	deselected map[string]bool,
	width, height int,
) *RegistryBrowser {
	repoInput := textinput.New()
	repoInput.Placeholder = "nginx  (or library/nginx)"
	repoInput.CharLimit = 256
	theme.StyleTextInput(&repoInput)
	repoInput.Focus()

	fi := textinput.New()
	fi.Placeholder = "filter tags…"
	fi.CharLimit = 128
	theme.StyleTextInput(&fi)

	b := &RegistryBrowser{
		registries:   registries,
		width:        width,
		height:       height,
		repoInput:    repoInput,
		selectedRegs: make(map[string]bool),
		focusedField: brFieldRepo,
		filterInput:  fi,
		tagTable:     *newTagTable(),
		scanCache:    make(map[string]cache.ImageScanEntry),
		state:        browserStateInput,
	}
	b.buildEntries(groups, deselected)
	b.resizeInputs()
	b.resizeTagTable()
	b.updateFocus()
	return b
}

// buildEntries expands every configured registry into the lines the picker
// shows: a group into its cached members under a header, anything else into
// itself.
//
// A selection is remembered as the entries that were *un*checked, so a member
// discovered since the last visit arrives checked like every other new one.
func (b *RegistryBrowser) buildEntries(groups map[string]cache.RegistryGroupEntry, deselected map[string]bool) {
	b.entries = nil
	b.rows = nil
	for _, reg := range b.registries {
		alias := browserAlias(reg)
		// Members share their group's host and therefore its single credential
		// entry, so they share the decision the group made about using it.
		mode := config.ResolveAuthMode(reg, nil)

		members := groups[reg.Slug].Members
		if reg.Kind != config.KindGroup || len(members) == 0 {
			// A group nobody has discovered yet is offered as itself: it is a
			// pullable registry too, and hiding it would be worse than listing
			// it without the members it may have.
			b.rows = append(b.rows, pickerRow{label: alias, entry: len(b.entries)})
			b.entries = append(b.entries, browserRegistryEntry{
				URL: reg.URL, Alias: alias, Slug: reg.Slug, authMode: mode,
				repoPrefix: reg.RepoPrefix,
				key:        reg.Slug,
			})
			continue
		}

		b.rows = append(b.rows, pickerRow{groupSlug: reg.Slug, label: alias, entry: -1})
		for _, m := range members {
			b.rows = append(b.rows, pickerRow{label: "  " + m.Alias, entry: len(b.entries)})
			b.entries = append(b.entries, browserRegistryEntry{
				URL:         m.URL,
				Alias:       m.Alias,
				repoPrefix:  m.RepoPrefix,
				Slug:        reg.Slug,
				ParentAlias: alias,
				ParentSlug:  reg.Slug,
				parentURL:   reg.URL,
				authMode:    mode,
				key:         memberKey(reg.Slug, m.URL, m.RepoPrefix),
			})
		}
	}

	b.selectedRegs = make(map[string]bool, len(b.entries))
	for _, e := range b.entries {
		b.selectedRegs[e.key] = !deselected[e.key]
	}
}

// memberKey names one member of a group. Scoping it by the group's slug is what
// keeps two groups fronting the same repository apart, and what keeps a member
// from colliding with a standalone registry keyed on its own slug.
//
// The URL alone will not do: every member of a path-routed group answers to the
// same host now, and the prefix is the whole of what tells them apart (§3.18).
func memberKey(groupSlug, memberURL, repoPrefix string) string {
	return groupSlug + "/" + memberURL + "/" + repoPrefix
}

// browserAlias returns what a registry is labelled with in the browser.
//
// With no alias it falls back to the entry's *address* rather than its URL: one
// line per proxy is one host repeated, so the URL alone would label every proxy
// of an instance identically (§3.18).
func browserAlias(reg config.RegistryItem) string {
	if reg.Alias != "" {
		return reg.Alias
	}
	return registryRef(reg.URL, reg.RepoPrefix)
}

// selected reports whether an entry is checked.
func (b *RegistryBrowser) selected(e browserRegistryEntry) bool { return b.selectedRegs[e.key] }

// groupState reports whether all, none or some of a group's members are checked.
func (b *RegistryBrowser) groupState(slug string) theme.CheckState {
	checked, total := 0, 0
	for _, e := range b.entries {
		if e.ParentSlug != slug {
			continue
		}
		total++
		if b.selected(e) {
			checked++
		}
	}
	switch {
	case total == 0 || checked == 0:
		return theme.CheckNone
	case checked == total:
		return theme.CheckAll
	default:
		return theme.CheckSome
	}
}

// toggleGroup checks every member of a group, or unchecks them when they were
// all already checked. A partial selection resolves upwards: the user is more
// likely to be completing it than discarding it.
func (b *RegistryBrowser) toggleGroup(slug string) {
	want := b.groupState(slug) != theme.CheckAll
	for _, e := range b.entries {
		if e.ParentSlug == slug {
			b.selectedRegs[e.key] = want
		}
	}
}

// Deselected returns the keys of the entries the user unchecked, which is what
// is remembered between visits.
func (b *RegistryBrowser) Deselected() []string {
	var out []string
	for _, e := range b.entries {
		if !b.selected(e) {
			out = append(out, e.key)
		}
	}
	return out
}

// SetSize updates dimensions and resizes internal components.
func (b *RegistryBrowser) SetSize(width, height int) {
	b.width = width
	b.height = height
	b.resizeInputs()
	b.resizeTagTable()
}

func (b *RegistryBrowser) resizeInputs() {
	w := max(b.width-22, 20)
	b.repoInput.SetWidth(w)
	b.filterInput.SetWidth(max(b.width-6, 10))
}

// resizeTagTable hands the table the viewport width.
//
// b.width is already the content width — the caller subtracted the borders —
// and datatable.Resize subtracts them itself, so they are added back here. The
// column solving, the Rule 116 remainder and the selected row's width are all
// its business now.
func (b *RegistryBrowser) resizeTagTable() {
	b.tagTable.Resize(b.width+2, max(b.height, 1))
}
package ociresources

import (
	"log"
	"time"

	tea "charm.land/bubbletea/v2"

	"github.com/anthnel/devdesk/internal/cache"
	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/registrymgr"
	"github.com/anthnel/devdesk/internal/trust"
)

// openMultiRegistryBrowser opens the multi-registry browser (triggered by 'b' on Images tab).
func (m Model) openMultiRegistryBrowser() (tea.Model, tea.Cmd) {
	if len(m.registries) == 0 {
		return m, m.footer.Warn("No registries configured — add one in the Registries tab")
	}
	// Config plus cache, read here and now: no network, no waiting, no state
	// that ignores esc (D13).
	// Reopening replaces a browser that may still have a lot in flight.
	m.registryBrowser.cancelInFlight()
	m.registryBrowser = newRegistryBrowser(m.registries, m.groupCache, m.browserDeselected, m.width-2, m.height)
	m.registryBrowser.SetScanCache(m.scanCache)
	m.registryBrowser.SetJobs(m.jobs, m.failures, m.contextName)
	return m, nil
}

// closeMultiRegistryBrowser drops the browser, remembering what the user
// unchecked so the next visit opens on the same selection.
func (m Model) closeMultiRegistryBrowser() (tea.Model, tea.Cmd) {
	if m.registryBrowser == nil {
		return m, nil
	}
	m.registryBrowser.cancelInFlight()
	deselected := m.registryBrowser.Deselected()
	m.registryBrowser = nil

	m.browserDeselected = make(map[string]bool, len(deselected))
	for _, key := range deselected {
		m.browserDeselected[key] = true
	}
	return m, saveBrowserSelectionCmd(deselected)
}

// handleMultiRegistryTagsLoaded incorporates tag results from one registry into the browser.
func (m Model) handleMultiRegistryTagsLoaded(msg MultiRegistryTagsLoadedMsg) (tea.Model, tea.Cmd) {
	if m.registryBrowser == nil || msg.Gen != m.registryBrowser.gen {
		return m, nil
	}
	if msg.Err != nil {
		log.Printf("ERROR [oci_resources] registry tags %s from %s: %v", msg.Repo, msg.RegistryURL, msg.Err)
		m.registryBrowser.AddRegistryTags(msg.EntryKey, msg.RegistryURL, msg.Alias, msg.Repo, nil)
		return m, nil
	}
	m.registryBrowser.SetScanCache(m.scanCache)
	m.registryBrowser.AddRegistryTags(msg.EntryKey, msg.RegistryURL, msg.Alias, msg.Repo, msg.

